import { afterAll, beforeEach, expect, test } from "bun:test";
import { mkdirSync, existsSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { checkManifest, precacheList, precacheVersion, serviceWorker } from "../src/bundle";

const repo = join(import.meta.dir, "..");
// Same depth below the repo as examples/counter, so module resolution matches a real project.
const dir = join(repo, "target", `tmp-pwa-${process.pid}`);

const MANIFEST = `{"name":"T","short_name":"T","display":"standalone","icons":[{"src":"icons/192.png","sizes":"192x192"},{"src":"icons/512.png","sizes":"512x512"}]}`;
const REGISTRATION = `if ("serviceWorker" in navigator) navigator.serviceWorker.register(new URL("../sw.js", import.meta.url));`;
const HEADER = "// Generated by xzor. Do not edit.";

rmSync(dir, { recursive: true, force: true });
mkdirSync(join(dir, "icons"), { recursive: true });
writeFileSync(join(dir, "tsconfig.json"), "{}");
writeFileSync(join(dir, "main.ts"), `export const app = document.title;\n`);
writeFileSync(join(dir, "styles.css"), "body { color: red }\n");
writeFileSync(join(dir, "icons", "192.png"), Buffer.from([1, 2, 3]));
writeFileSync(join(dir, "icons", "512.png"), Buffer.from([4, 5, 6]));
writeFileSync(
  join(dir, "index.html"),
  `<!doctype html>\n<link rel="stylesheet" href="styles.css">\n<link rel="icon" href="https://x/y.png">\n<a href="#top">top</a>\n<script type="module" src="./dist/main.js"></script>\n`,
);

afterAll(() => rmSync(dir, { recursive: true, force: true }));

// Each test starts without a manifest, worker or build output.
beforeEach(() => {
  for (const f of ["manifest.webmanifest", "sw.js"]) rmSync(join(dir, f), { force: true });
  rmSync(join(dir, "dist"), { recursive: true, force: true });
});

const bundle = (...extra: string[]) => {
  const run = Bun.spawnSync(["bun", join(repo, "src", "bundle.ts"), join(dir, "main.ts"), join(dir, "dist"), ...extra], { cwd: repo });
  expect(run.exitCode, run.stderr.toString()).toBe(0);
  return { out: run.stdout.toString(), err: run.stderr.toString() };
};

test("a well-formed manifest has no problems", () => {
  expect(checkManifest(MANIFEST, dir)).toEqual([]);
});

test("an empty manifest reports the missing fields and icon sizes", () => {
  const problems = checkManifest("{}", dir).join("\n");
  expect(problems).toContain("name");
  expect(problems).toContain("192x192");
  expect(problems).toContain("512x512");
  expect(problems).toContain("display");
});

test("broken JSON is one problem", () => {
  const problems = checkManifest("{", dir);
  expect(problems).toHaveLength(1);
  expect(problems[0]).toContain("JSON");
});

test("an icon that is not on disk is reported", () => {
  const problems = checkManifest(MANIFEST.replace("icons/512.png", "icons/missing.png"), dir).join("\n");
  expect(problems).toContain("icons/missing.png");
});

test("root-absolute icons are the project's files", () => {
  const rooted = MANIFEST.replaceAll('"icons/', '"/icons/');
  expect(checkManifest(rooted, dir)).toEqual([]);
  writeFileSync(join(dir, "manifest.webmanifest"), rooted);
  expect(precacheList(dir, [])).toContain("icons/512.png");
});

test("the precache list holds the app shell, local page assets and non-map outputs", () => {
  writeFileSync(join(dir, "manifest.webmanifest"), MANIFEST);
  expect(precacheList(dir, [join(dir, "dist", "main.js"), join(dir, "dist", "main.js.map")])).toEqual([
    "./",
    "dist/main.js",
    "icons/192.png",
    "icons/512.png",
    "index.html",
    "manifest.webmanifest",
    "styles.css",
  ]);
});

test("the precache list skips root-absolute refs, escapes and data- attributes", () => {
  const index = readFileSync(join(dir, "index.html"), "utf8");
  writeFileSync(join(dir, "abs.css"), "a{}");
  writeFileSync(join(dir, "data.png"), "d");
  writeFileSync(join(dir, "index.html"), `${index}<link href="/abs.css">\n<link href="icons/../styles.css">\n<img data-src="data.png" data-href="data.png">\n<img\nsrc="data.png">\n<img src="../outside.png">\n`);
  try {
    const files = precacheList(dir, []);
    expect(files).not.toContain("abs.css");
    expect(files).not.toContain("/abs.css");
    expect(files.filter((f) => f === "styles.css")).toHaveLength(1);
    expect(files.filter((f) => f === "data.png")).toHaveLength(1);
    expect(files.some((f) => f.includes("..") || f.startsWith("/"))).toBe(false);
  } finally {
    writeFileSync(join(dir, "index.html"), index);
    rmSync(join(dir, "abs.css"));
    rmSync(join(dir, "data.png"));
  }
});

test("data- attributes alone precache nothing", () => {
  const index = readFileSync(join(dir, "index.html"), "utf8");
  writeFileSync(join(dir, "data.png"), "d");
  writeFileSync(join(dir, "index.html"), `${index}<img data-src="data.png" data-href="data.png">\n`);
  try {
    expect(precacheList(dir, [])).not.toContain("data.png");
  } finally {
    writeFileSync(join(dir, "index.html"), index);
    rmSync(join(dir, "data.png"));
  }
});

test("the precache list tolerates a missing manifest", () => {
  expect(precacheList(dir, [])).toContain("index.html");
});

test("the worker carries its version and file list", () => {
  const src = serviceWorker("abc", ["./", "index.html"]);
  expect(src.startsWith(HEADER)).toBe(true);
  expect(src).toContain(`"xzor-abc"`);
  expect(src).toContain(`["./","index.html"]`);
  expect(src).toContain("ignoreVary");
  expect(src).toContain(`cache: "reload"`);
});

test("renaming an asset with the same bytes changes the version", () => {
  writeFileSync(join(dir, "a.bin"), "same");
  writeFileSync(join(dir, "b.bin"), "same");
  expect(precacheVersion(dir, ["a.bin"], new Map())).not.toBe(precacheVersion(dir, ["b.bin"], new Map()));
  expect(precacheVersion(dir, ["a.bin"], new Map())).toBe(precacheVersion(dir, ["a.bin"], new Map()));
  rmSync(join(dir, "a.bin"));
  rmSync(join(dir, "b.bin"));
});

test("the bundle's worker version covers the entry bundle with its registration line", () => {
  writeFileSync(join(dir, "manifest.webmanifest"), MANIFEST);
  bundle();
  const entry = readFileSync(join(dir, "dist", "main.js"), "utf8");
  const files = precacheList(dir, [join(dir, "dist", "main.js")]);
  const version = readFileSync(join(dir, "sw.js"), "utf8").match(/"xzor-([0-9a-f]+)"/)![1];
  expect(precacheVersion(dir, files, new Map([["dist/main.js", entry]]))).toBe(version);
});

test("a manifest makes the bundle install a service worker, and removing it undoes that", () => {
  bundle();
  const plain = readFileSync(join(dir, "dist", "main.js"), "utf8");
  expect(existsSync(join(dir, "sw.js"))).toBe(false);

  writeFileSync(join(dir, "manifest.webmanifest"), MANIFEST);
  const { out } = bundle();
  const worker = readFileSync(join(dir, "sw.js"), "utf8");
  expect(worker.startsWith(HEADER)).toBe(true);
  const built = readFileSync(join(dir, "dist", "main.js"), "utf8");
  expect(built).toMatch(/\/\/# sourceMappingURL=main\.js\.map\n?$/);
  expect(built).toContain(`${REGISTRATION}\n//# sourceMappingURL=`);
  // `xzor dev` reloads on the printed output paths; the worker is not one of them.
  expect(out).not.toContain("sw.js");

  bundle();
  expect(readFileSync(join(dir, "sw.js"), "utf8")).toBe(worker);

  bundle("--watch");
  expect(existsSync(join(dir, "sw.js"))).toBe(true);
  expect(readFileSync(join(dir, "dist", "main.js"), "utf8")).not.toContain(REGISTRATION);

  rmSync(join(dir, "manifest.webmanifest"));
  bundle();
  expect(existsSync(join(dir, "sw.js"))).toBe(false);
  expect(readFileSync(join(dir, "dist", "main.js"), "utf8")).toBe(plain);
}, 60_000);

test("--watch neither writes nor deletes the worker", () => {
  writeFileSync(join(dir, "sw.js"), `${HEADER}\n`);
  bundle("--watch");
  expect(existsSync(join(dir, "sw.js"))).toBe(true);
  rmSync(join(dir, "sw.js"));
}, 60_000);

test("a hand-written worker is never touched", () => {
  const mine = `// mine\nself.addEventListener("fetch", () => {});\n`;
  writeFileSync(join(dir, "sw.js"), mine);
  bundle();
  expect(readFileSync(join(dir, "sw.js"), "utf8")).toBe(mine);
  rmSync(join(dir, "sw.js"));
}, 60_000);

test("a broken manifest warns but still builds", () => {
  writeFileSync(join(dir, "manifest.webmanifest"), "{");
  const { err } = bundle();
  expect(err).toContain("xzor: manifest.webmanifest:");
  expect(readFileSync(join(dir, "sw.js"), "utf8").startsWith(HEADER)).toBe(true);
}, 60_000);
